package cn.zhuatech.testagent.service;import org.junit.jupiter.api.Test;import static org.assertj.core.api.Assertions.assertThat;class TestReleaseCertificationServiceTest{private final TestReleaseCertificationService s=new TestReleaseCertificationService();@Test void certifiesTestedRelease(){var r=s.assess(new TestReleaseCertificationService.Request("R1",true,true,true,true,true,true,0,true,true,true,true));assertThat(r.decision()).isEqualTo(TestReleaseCertificationService.Decision.CERTIFY);}@Test void conditionallyCertifiesOperationalGaps(){var r=s.assess(new TestReleaseCertificationService.Request("R2",true,true,true,true,true,true,0,true,false,false,true));assertThat(r.actions()).hasSize(2);}@Test void blocksUntestedRelease(){var r=s.assess(new TestReleaseCertificationService.Request("R3",false,false,false,false,false,false,3,false,true,true,false));assertThat(r.blockers()).hasSize(9);}}
